import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🎯 OBJECTIFS", 'fin', apropos("Un thermomètre numérique affiche « 24,3 °C ». Comment un petit circuit peut-il **connaître** une température et **l'écrire en chiffres** ?", "Un **capteur** transforme la température en une **tension électrique**. Cette tension varie **de façon continue** (elle est analogique). L'Arduino la **mesure** avec un **convertisseur** qui la transforme en **nombre**. Un petit calcul donne enfin la température en °C.\n\nDans cette séance, tu suis toute cette chaîne : **capteur LM35 → tension → nombre → température**.")),
    ("## 📚 PARTIE 1", 'fin', clair("Un signal **analogique** varie **de façon continue** : il peut prendre **toutes** les valeurs possibles (la température d'une pièce, la tension d'une pile qui se vide). Un signal **numérique** ne prend que **quelques valeurs précises** (0 ou 1).\n\nL'Arduino **ne comprend que des nombres** : pour utiliser un capteur analogique, il faut donc **convertir**.") + "\n" + verifie(
        ("La température d'une pièce est-elle un signal analogique ou numérique ?", "**Analogique** : elle varie de façon continue, sans « sauts »."),
        ("Un interrupteur ouvert / fermé est-il analogique ou numérique ?", "**Numérique** : il n'a que deux états."),
        ("Pourquoi doit-on convertir un signal analogique pour l'Arduino ?", "Parce que l'Arduino ne traite que des **nombres** : il faut transformer la tension en un nombre.")) + "\n" + retenir("Analogique = continu ; numérique = quelques valeurs précises.")),
    ("## 📚 PARTIE 2", 'fin', clair("Le **convertisseur analogique-numérique (ADC)** transforme une tension en un **nombre entier**. L'Arduino Uno a un ADC de **10 bits** : il dispose de $2^{10} = 1\\,024$ niveaux, donc de **0 à 1023**.\n\nLa plage mesurée est **0 à 5 V**. Chaque niveau représente donc $\\dfrac{5}{1023} \\approx 4{,}9\\,\\mathrm{mV}$.\n\n**Conversion :** $U = \\text{valeur} \\times \\dfrac{5}{1023}$.") + "\n" + verifie(
        ("Que renvoie `analogRead()` pour une tension de 0 V ? Et pour 5 V ?", "**0** pour 0 V ; **1023** pour 5 V."),
        ("Quelle tension correspond à une valeur de 512 ?", "$U = 512 \\times \\dfrac{5}{1023} \\approx 2{,}5\\,\\mathrm{V}$ (la moitié de la plage)."),
        ("Pourquoi 1024 niveaux ?", "Parce que l'ADC a **10 bits** : $2^{10} = 1\\,024$.")) + "\n" + retenir("`analogRead()` donne un nombre de 0 à 1023.", "$U = \\text{valeur} \\times \\dfrac{5}{1023}$.")),
    ("## 📚 PARTIE 3", 'fin', clair("Le **LM35** est un capteur de température très simple : il possède **trois broches** (+5 V, signal, GND) et délivre **10 mV par degré Celsius**. À 25 °C, il sort donc $25 \\times 10 = 250\\,\\mathrm{mV} = 0{,}25\\,\\mathrm{V}$.") + "\n" + erreurs("Inverser le **+5 V** et le **GND** : le LM35 chauffe et peut être détruit.", "Brancher la broche de signal ailleurs que sur une entrée **analogique** (A0, A1…).") + "\n" + verifie(
        ("Quelle tension délivre un LM35 à 30 °C ?", "$30 \\times 10\\,\\mathrm{mV} = 300\\,\\mathrm{mV} = 0{,}3\\,\\mathrm{V}$."),
        ("Quelle est la sensibilité du LM35 ?", "**10 mV par °C**."),
        ("Sur quelle broche de l'Arduino branche-t-on la broche de signal du LM35 ?", "Sur une **entrée analogique**, par exemple **A0**.")) + "\n" + retenir("LM35 : 10 mV par °C, trois broches (+5 V, signal, GND).")),
    ("## 📚 PARTIE 4", 'fin', clair("Pour passer du capteur à la température, on suit **trois étapes** :\n\n1. **Lire** le nombre : `valeur = analogRead(A0)`.\n2. **Convertir en tension** : $U = \\text{valeur} \\times \\dfrac{5}{1023}$.\n3. **Convertir en température** : $T = U \\times 100$ (car 10 mV par °C, soit 100 °C par volt).\n\n**Exemple :** valeur = 51 → $U = 51 \\times \\dfrac{5}{1023} \\approx 0{,}249\\,\\mathrm{V}$ → $T \\approx 24{,}9\\,°\\mathrm{C}$.") + "\n" + verifie(
        ("`analogRead` renvoie 102. Quelle est la température ?", "$U = 102 \\times \\dfrac{5}{1023} \\approx 0{,}499\\,\\mathrm{V}$ ; $T \\approx 49{,}9\\,°\\mathrm{C}$."),
        ("Pourquoi multiplie-t-on la tension par 100 ?", "Parce que le LM35 délivre **10 mV par °C** : 1 V correspond à **100 °C**."),
        ("Que se passe-t-il si on oublie de diviser par 1023 ?", "On obtient un nombre **beaucoup trop grand** qui n'a plus de sens comme température.")) + "\n" + retenir("lire → tension → température : $T = \\text{valeur} \\times \\dfrac{5}{1023} \\times 100$.")),
    ("## 📚 PARTIE 5", 'fin', clair("Dans le programme, on écrit exactement ces trois étapes : on **lit** avec `analogRead`, on **calcule**, on **affiche** avec `Serial.println`. On utilise des nombres à virgule (`float`) pour ne pas perdre les décimales. Pour des mesures plus stables, on fait une **moyenne** de plusieurs lectures.") + "\n" + verifie(
        ("Pourquoi utilise-t-on le type `float` pour la température ?", "Parce qu'une température a des **décimales** : un `int` les perdrait."),
        ("À quoi sert la moyenne de plusieurs mesures ?", "À **lisser le bruit** : une seule mesure peut être perturbée.")) + "\n" + retenir("`analogRead` → calcul en `float` → `Serial.println`.")),
]
